// ─── File: src/test/java/com/bank/nullkey/NullKeyTest.java ───
package com.bank.nullkey;

import org.junit.jupiter.api.Test;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;
import static org.assertj.core.api.Assertions.*;

class NullKeyTest {

    @Test
    void hashMap_allowsNullKey() {
        Map<String, String> map = new HashMap<>();
        map.put(null, "unknown-account");
        map.put("SAV2001", null);

        assertThat(map.get(null)).isEqualTo("unknown-account");
        assertThat(map.get("SAV2001")).isNull();
        assertThat(map).hasSize(2);
    }

    @Test
    void linkedHashMap_allowsNullKey() {
        Map<String, String> map = new LinkedHashMap<>();
        map.put(null, "value");
        assertThat(map.get(null)).isEqualTo("value");
    }

    @Test
    void treeMap_rejectsNullKey() {
        TreeMap<String, String> map = new TreeMap<>();
        assertThatThrownBy(() -> map.put(null, "value"))
            .isInstanceOf(NullPointerException.class);
        // null.compareTo() → NPE!
    }

    @Test
    void treeMap_allowsNullValue() {
        TreeMap<String, String> map = new TreeMap<>();
        map.put("SAV2001", null);  // null VALUE is fine!
        assertThat(map.get("SAV2001")).isNull();
    }

    @Test
    void treeMap_nullSafeComparator() {
        TreeMap<String, String> map = new TreeMap<>(
            Comparator.nullsFirst(Comparator.naturalOrder()));
        map.put(null, "no-key");
        map.put("SAV2001", "Rajesh");
        map.put("CUR3001", "Priya");

        assertThat(new ArrayList<>(map.keySet()))
            .containsExactly(null, "CUR3001", "SAV2001");  // null first!
    }

    @Test
    void concurrentHashMap_rejectsBothNull() {
        ConcurrentHashMap<String, String> map = new ConcurrentHashMap<>();
        assertThatThrownBy(() -> map.put(null, "v")).isInstanceOf(NullPointerException.class);
        assertThatThrownBy(() -> map.put("k", null)).isInstanceOf(NullPointerException.class);
    }

    @Test
    void hashtable_rejectsBothNull() {
        Hashtable<String, String> map = new Hashtable<>();
        assertThatThrownBy(() -> map.put(null, "v")).isInstanceOf(NullPointerException.class);
        assertThatThrownBy(() -> map.put("k", null)).isInstanceOf(NullPointerException.class);
    }
}
